ALTER TABLE quotes ADD COLUMN quote_no text UNIQUE;
CREATE TABLE quote_number_counters(business_date date NOT NULL,hospital_id uuid NOT NULL REFERENCES hospitals,value integer NOT NULL CHECK(value BETWEEN 1 AND 999),PRIMARY KEY(business_date,hospital_id));
WITH numbered AS(SELECT q.id,o.hospital_id,(o.created_at AT TIME ZONE 'Asia/Shanghai')::date AS day,row_number() OVER(PARTITION BY (o.created_at AT TIME ZONE 'Asia/Shanghai')::date,o.hospital_id ORDER BY q.id) AS number FROM quotes q JOIN purchase_orders o ON o.id=q.purchase_order_id) UPDATE quotes q SET quote_no='BJ-'||to_char(n.day,'YYYYMMDD')||'-'||right(n.hospital_id::text,6)||'-'||lpad(n.number::text,3,'0') FROM numbered n WHERE q.id=n.id;
INSERT INTO quote_number_counters SELECT (o.created_at AT TIME ZONE 'Asia/Shanghai')::date,o.hospital_id,count(*) FROM quotes q JOIN purchase_orders o ON o.id=q.purchase_order_id GROUP BY 1,2;
ALTER TABLE purchase_orders DROP CONSTRAINT purchase_orders_status_check;
ALTER TABLE purchase_orders ADD CONSTRAINT purchase_orders_status_check CHECK(status IN('draft','frozen','quote_draft','quote_exported','quote_sent','completed','voided'));
ALTER TABLE quotes ADD COLUMN confirmed_version_id uuid REFERENCES quote_versions(id);
ALTER TABLE quotes ADD COLUMN status text NOT NULL DEFAULT 'active' CHECK(status IN('active','completed'));
ALTER TABLE quote_versions ADD COLUMN document jsonb;
ALTER TABLE quote_versions ADD COLUMN basis_evidence jsonb;
ALTER TABLE quote_versions ADD COLUMN snapshot_hash text;
ALTER TABLE quote_versions ADD COLUMN first_exported_at timestamptz;
ALTER TABLE quote_versions ADD COLUMN first_sent_at timestamptz;
ALTER TABLE quote_versions ADD COLUMN use_invalidated_at timestamptz;
ALTER TABLE quote_versions ADD COLUMN hospital_confirmed_at timestamptz;
ALTER TABLE quote_versions ADD COLUMN confirmation_recorded_at timestamptz;
ALTER TABLE quote_versions ADD COLUMN backfill_reason text;
ALTER TABLE quote_versions ADD COLUMN active_export_id uuid;
ALTER TABLE quote_versions ADD COLUMN export_generation integer NOT NULL DEFAULT 0;
CREATE TABLE quote_export_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version_id uuid NOT NULL REFERENCES quote_versions,order_id uuid NOT NULL REFERENCES purchase_orders,revision_id uuid NOT NULL REFERENCES purchase_order_revisions,generation integer NOT NULL,input_version integer NOT NULL,format text NOT NULL CHECK(format IN('pdf','xlsx')),document jsonb NOT NULL,basis_evidence jsonb NOT NULL,snapshot_hash text NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','succeeded','failed')),created_at timestamptz NOT NULL,deadline timestamptz NOT NULL,UNIQUE(version_id,generation));
ALTER TABLE quote_versions ADD CONSTRAINT active_export_reference FOREIGN KEY(active_export_id) REFERENCES quote_export_attempts;
CREATE TABLE export_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),export_id uuid UNIQUE NOT NULL REFERENCES quote_export_attempts,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','running','succeeded','failed')),attempts integer NOT NULL DEFAULT 0,error text,retry_at timestamptz NOT NULL,lease_until timestamptz,claim_generation integer NOT NULL DEFAULT 0,file_id uuid,created_at timestamptz NOT NULL);
CREATE INDEX export_jobs_queue ON export_jobs(retry_at,created_at) WHERE state='queued';
CREATE TABLE quote_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),export_id uuid UNIQUE NOT NULL REFERENCES quote_export_attempts,version_id uuid NOT NULL REFERENCES quote_versions,object_key text UNIQUE NOT NULL,filename text NOT NULL,sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),size integer NOT NULL CHECK(size>0),content_type text NOT NULL,format text NOT NULL CHECK(format IN('pdf','xlsx')),created_at timestamptz NOT NULL);
ALTER TABLE export_jobs ADD CONSTRAINT export_job_file_reference FOREIGN KEY(file_id) REFERENCES quote_files;
CREATE TABLE quote_sends(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version_id uuid NOT NULL REFERENCES quote_versions,channel text NOT NULL,remark text NOT NULL,recorded_by uuid NOT NULL REFERENCES users,recorded_at timestamptz NOT NULL);
CREATE TABLE receivables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_order_id uuid UNIQUE NOT NULL REFERENCES purchase_orders,confirmed_version_id uuid UNIQUE NOT NULL REFERENCES quote_versions,amount numeric(12,2) NOT NULL CHECK(amount>=0),payment_term_days integer NOT NULL CHECK(payment_term_days BETWEEN 0 AND 3650),due_date date NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE file_download_tickets(token_hash text PRIMARY KEY,file_id uuid NOT NULL REFERENCES quote_files,actor_id uuid NOT NULL REFERENCES users,session_id uuid NOT NULL REFERENCES auth_sessions,expires_at timestamptz NOT NULL);
CREATE FUNCTION protect_frozen_quote_lines() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP IN('UPDATE','DELETE') AND EXISTS(SELECT 1 FROM quote_versions WHERE id=OLD.version_id AND first_exported_at IS NOT NULL) THEN RAISE EXCEPTION 'frozen quote lines are immutable';END IF;IF TG_OP IN('INSERT','UPDATE') AND EXISTS(SELECT 1 FROM quote_versions WHERE id=NEW.version_id AND first_exported_at IS NOT NULL) THEN RAISE EXCEPTION 'frozen quote lines are immutable';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER frozen_quote_lines_guard BEFORE INSERT OR UPDATE OR DELETE ON quote_lines FOR EACH ROW EXECUTE FUNCTION protect_frozen_quote_lines();
CREATE FUNCTION protect_frozen_quote_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' AND OLD.first_exported_at IS NOT NULL THEN RAISE EXCEPTION 'frozen quote version cannot be deleted';END IF;IF TG_OP='UPDATE' AND OLD.first_exported_at IS NOT NULL THEN IF ROW(NEW.document,NEW.basis_evidence,NEW.snapshot_hash,NEW.hospital_valid_until,NEW.quote_id,NEW.revision_id,NEW.version_no,NEW.first_exported_at) IS DISTINCT FROM ROW(OLD.document,OLD.basis_evidence,OLD.snapshot_hash,OLD.hospital_valid_until,OLD.quote_id,OLD.revision_id,OLD.version_no,OLD.first_exported_at) THEN RAISE EXCEPTION 'frozen quote snapshot is immutable';END IF;IF OLD.use_invalidated_at IS NOT NULL AND NEW.use_invalidated_at IS DISTINCT FROM OLD.use_invalidated_at THEN RAISE EXCEPTION 'first invalidation is immutable';END IF;END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER frozen_quote_version_guard BEFORE UPDATE OR DELETE ON quote_versions FOR EACH ROW EXECUTE FUNCTION protect_frozen_quote_version();
CREATE FUNCTION protect_export_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.version_id,NEW.order_id,NEW.revision_id,NEW.generation,NEW.input_version,NEW.format,NEW.document,NEW.basis_evidence,NEW.snapshot_hash,NEW.created_at,NEW.deadline) IS DISTINCT FROM ROW(OLD.version_id,OLD.order_id,OLD.revision_id,OLD.generation,OLD.input_version,OLD.format,OLD.document,OLD.basis_evidence,OLD.snapshot_hash,OLD.created_at,OLD.deadline) THEN RAISE EXCEPTION 'prepared export snapshot is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER export_snapshot_guard BEFORE UPDATE ON quote_export_attempts FOR EACH ROW EXECUTE FUNCTION protect_export_snapshot();

ALTER TABLE quote_lines ADD COLUMN public_remark text NOT NULL DEFAULT '' CHECK(length(public_remark)<=500);
